Title: 'Best 5 Movies to Watch in 2024'
```javascript
// Implement a function that returns a title for a book.
function createTitle(title, prefix) {
  // Use the `split()` method to create an array of words.
  const words = title.split(' ');
  // Capitalize the first letter of the first word.
  const firstWord = words[0].charAt(0).toUpperCase() + words[0].slice(1);
  // Join the words with a space.
  const titleWithoutSpaces = firstWord + words.slice(1).join('');
  // Use the `replace()` method to replace spaces with hyphens.
  const titleWithHyphens = titleWithoutSpaces.replace(/ /g, '-');
  // Concatenate the prefix with the title and return it.
  return `${prefix} ${titleWithHyphens}`;
}

// Example usage:
const title = 'the meaning of life';
const prefix = 'best';
console.log(createTitle(title, prefix));
// Output: 'Best-The-Meaning-Of-Life'
